package appserver

import (
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"strconv"
	"strings"

	"github.com/cidverse/cid/pkg/app/appgitlab"
	"github.com/labstack/echo/v5"
	"go.yaml.in/yaml/v4"
)

// gitlabFiles maps the file name used in /v1/gitlab/<project_id>/<source>/<ref>/<file> to the generated file path.
// URLs end with the file name and carry no query string: GitLab checks File.basename(location) against /\.(yml|yaml)$/,
// so a trailing query string would fail the include.
var gitlabFiles = map[string]string{
	"gitlab-ci.yml":     ".gitlab-ci.yml",
	"state-gitlab.json": ".cid/state-gitlab.json",
}

// gitlabBootstrap returns a static .gitlab-ci.yml that includes the pipeline rendered for the current project and ref.
// Only variables GitLab allows in include sections are used (CI_PROJECT_ID, CI_PIPELINE_SOURCE, CI_COMMIT_REF_NAME);
// GitLab expands unknown variables (e.g. CI_COMMIT_SHA) to an empty string.
func (s *Server) gitlabBootstrap(c *echo.Context) error {
	if s.cfg.PublicURL == "" {
		return echo.NewHTTPError(http.StatusServiceUnavailable, "CID_SERVER_PUBLIC_URL is not configured")
	}

	content := fmt.Sprintf(`# Generated by cid app-server, includes the pipeline rendered by cid for this project.
include:
  - remote: "%s/v1/gitlab/${CI_PROJECT_ID}/${CI_PIPELINE_SOURCE}/${CI_COMMIT_REF_NAME}/gitlab-ci.yml"
`, s.cfg.PublicURL)

	return c.String(http.StatusOK, content)
}

// gitlabFile serves /v1/gitlab/<project_id>/<source>/<ref>/<file>, the ref may contain slashes (e.g. feature/x).
// GitLab inserts the ref unescaped, so refs containing '#' or '%' arrive truncated / mangled.
// Source and ref are currently only logged: pipelines are always rendered for the default branch (see ROADMAP.md).
//
// If the pipeline cannot be provided, gitlab-ci.yml requests get a pipeline with a single failing job that prints the reason
// (status 200), since a failed include only shows a generic "Remote file could not be fetched" error in GitLab.
func (s *Server) gitlabFile(c *echo.Context) error {
	rest := c.Param("*")
	idx := strings.LastIndex(rest, "/")
	if idx <= 0 {
		return echo.NewHTTPError(http.StatusNotFound, "expected /v1/gitlab/<project_id>/<source>/<ref>/<file>")
	}
	ref, name := rest[:idx], rest[idx+1:]
	file, ok := gitlabFiles[name]
	if !ok {
		return echo.NewHTTPError(http.StatusNotFound, fmt.Sprintf("unknown file %s", name))
	}

	content, err := s.gitlabFileContent(c, c.Param("project_id"), c.Param("source"), ref, file)
	if err != nil {
		var pe *pipelineError
		if file == ".gitlab-ci.yml" && errors.As(err, &pe) {
			slog.With("project_id", c.Param("project_id")).With("ref", ref).With("status", pe.status).With("reason", pe.message).Info("serving error pipeline")
			return c.String(http.StatusOK, s.gitlabErrorPipeline(pe.message))
		}
		return toHTTPError(err)
	}

	return c.String(http.StatusOK, content)
}

// gitlabFileContent returns the content of a generated file; failures are *pipelineError, except for a cancelled request context.
func (s *Server) gitlabFileContent(c *echo.Context, rawProjectId string, source string, ref string, file string) (string, error) {
	projectId, err := strconv.ParseInt(rawProjectId, 10, 64)
	if err != nil {
		return "", newPipelineError(http.StatusBadRequest, fmt.Sprintf("invalid project_id %q", rawProjectId))
	}
	slog.With("project_id", projectId).With("source", source).With("ref", ref).With("file", file).Debug("gitlab pipeline file requested")

	pipeline, err := s.resolvePipeline(c, projectId)
	if err != nil {
		return "", err
	}
	content, ok := pipeline.WorkflowContent[file]
	if !ok {
		return "", newPipelineError(http.StatusNotFound, fmt.Sprintf("cid generated no %s for this project", file))
	}

	return content, nil
}

// gitlabErrorPipelineJob is the only job of an error pipeline.
type gitlabErrorPipelineJob struct {
	Stage     string                         `yaml:"stage"`
	Tags      []string                       `yaml:"tags,omitempty"`
	Variables map[string]gitlabErrorVariable `yaml:"variables"`
	Script    []string                       `yaml:"script"`
	Rules     []map[string]string            `yaml:"rules"`
}

type gitlabErrorVariable struct {
	Value  string `yaml:"value"`
	Expand bool   `yaml:"expand"`
}

// gitlabErrorPipeline renders a pipeline with one job that prints message and fails.
// The message is passed as an unexpanded CI/CD variable, so it needs no shell or YAML escaping. The job runs on the server's
// runner tags for the test stage (project overrides are unknown without a render), uses the runner's default image and runs
// for every pipeline source (rules: when: always), including merge request pipelines.
func (s *Server) gitlabErrorPipeline(message string) string {
	pipeline := map[string]gitlabErrorPipelineJob{
		"cid-pipeline-error": {
			Stage: "test", // a default stage; GitLab rejects pipelines whose only jobs are in .pre / .post
			Tags:  appgitlab.BaseRunnerTags(s.cfg.RunnerTags).ForStage("test"),
			Variables: map[string]gitlabErrorVariable{
				"CID_PIPELINE_ERROR": {Value: message, Expand: false},
			},
			Script: []string{
				`echo "cid could not generate the pipeline for this project: $CID_PIPELINE_ERROR" >&2`,
				"exit 1",
			},
			Rules: []map[string]string{{"when": "always"}},
		},
	}

	out, err := yaml.Marshal(pipeline)
	if err != nil { // cannot happen for these types
		slog.With("err", err).Error("Failed to render error pipeline")
		return ""
	}

	return "# Generated by cid app-server: the pipeline could not be generated, see the job log.\n" + string(out)
}
